  id, "userId", parada_id, "weekIndex", "weekLabel", "dateRange", "publishedAt", "postedAt",
  likes, comments, reposts, chart_type, week_start_date, is_published, max_items, community_id
)
SELECT
  'cmr5sa3sk0247ngp4l01qqxw8',
  ctx.user_id,
  ctx.parada_id,
  200936,
  'Semana 36 - 2009',
  '31/08/2009 a 06/09/2009',
  '2009-09-05 03:00:00.000+00'::timestamptz,
  '2026-07-04 03:09:24.788+00'::timestamptz,
  0, 0, 0,
  'SONGS',
  '2009-08-31'::date,
  true,
  20,
  ctx.community_id
FROM _ucc_ctx ctx
WHERE NOT EXISTS (SELECT 1 FROM "Chart" c WHERE c.parada_id = ctx.parada_id AND c."weekIndex" = 200936);

