  id, "userId", parada_id, "weekIndex", "weekLabel", "dateRange", "publishedAt", "postedAt",
  likes, comments, reposts, chart_type, week_start_date, is_published, max_items, community_id
)
SELECT
  'cmr5scp68038lngp4ae8j2o7s',
  ctx.user_id,
  ctx.parada_id,
  201042,
  'Semana 42 - 2010',
  '18/10/2010 a 24/10/2010',
  '2010-10-23 02:00:00.000+00'::timestamptz,
  '2026-07-04 03:11:25.808+00'::timestamptz,
  0, 0, 0,
  'SONGS',
  '2010-10-18'::date,
  true,
  20,
  ctx.community_id
FROM _ucc_ctx ctx
WHERE NOT EXISTS (SELECT 1 FROM "Chart" c WHERE c.parada_id = ctx.parada_id AND c."weekIndex" = 201042);

