  id, "userId", parada_id, "weekIndex", "weekLabel", "dateRange", "publishedAt", "postedAt",
  likes, comments, reposts, chart_type, week_start_date, is_published, max_items, community_id
)
SELECT
  'cmr5so88f0ayjngp4y9d2ker2',
  ctx.user_id,
  ctx.parada_id,
  201840,
  'Semana 40 - 2018',
  '01/10/2018 a 07/10/2018',
  '2018-10-06 03:00:00.000+00'::timestamptz,
  '2026-07-04 03:20:23.728+00'::timestamptz,
  0, 0, 0,
  'SONGS',
  '2018-10-01'::date,
  true,
  20,
  ctx.community_id
FROM _ucc_ctx ctx
WHERE NOT EXISTS (SELECT 1 FROM "Chart" c WHERE c.parada_id = ctx.parada_id AND c."weekIndex" = 201840);

