  likes, comments, reposts, chart_type, week_start_date, is_published, max_items, community_id
)
SELECT
  'cmr5souy80ba2ngp47yua1hbm',
  ctx.user_id,
  ctx.parada_id,
  201905,
  'Semana 5 - 2019',
  '28/01/2019 a 03/02/2019',
  '2019-02-02 02:00:00.000+00'::timestamptz,
  '2026-07-04 03:20:53.168+00'::timestamptz,
  0, 0, 0,
  'SONGS',
  '2019-01-28'::date,
  true,
  20,
  ctx.community_id
FROM _ucc_ctx ctx
WHERE NOT EXISTS (SELECT 1 FROM "Chart" c WHERE c.parada_id = ctx.parada_id AND c."weekIndex" = 201905);

