  likes, comments, reposts, chart_type, week_start_date, is_published, max_items, community_id
)
SELECT
  'cmr5sq75e0bttngp4dcaxoz78',
  ctx.user_id,
  ctx.parada_id,
  201934,
  'Semana 34 - 2019',
  '19/08/2019 a 25/08/2019',
  '2019-08-24 03:00:00.000+00'::timestamptz,
  '2026-07-04 03:21:55.634+00'::timestamptz,
  0, 0, 0,
  'SONGS',
  '2019-08-19'::date,
  true,
  20,
  ctx.community_id
FROM _ucc_ctx ctx
WHERE NOT EXISTS (SELECT 1 FROM "Chart" c WHERE c.parada_id = ctx.parada_id AND c."weekIndex" = 201934);

